<script setup>import{ref,onMounted}from'vue';import{RouterLink}from'vue-router';import api from'../services/api';import{addToCart}from'../stores';const products=ref([]),categories=ref([]),search=ref(''),category=ref(''),loading=ref(true);async function load(){loading.value=true;try{const[p,c]=await Promise.all([api.get('/products',{params:{search:search.value,categoryId:category.value||undefined}}),api.get('/categories')]);products.value=p.data.products||p.data;categories.value=c.data.categories||c.data}catch{}finally{loading.value=false}}onMounted(load)</script><template><section><div class="rounded-3xl bg-slate-950 px-6 py-12 text-white md:px-12"><p class="text-sm font-bold uppercase tracking-[.2em] text-indigo-300">One company · curated catalog</p><h1 class="mt-3 max-w-3xl text-4xl font-black md:text-6xl">Shop products. Share links. Earn commissions.</h1><p class="mt-5 max-w-xl text-slate-300">A professional commerce experience built around categories, checkout and affiliate growth.</p></div><div class="mt-7 flex gap-3"><input v-model="search" @keyup.enter="load" class="flex-1 rounded-xl border bg-white px-4 py-3" placeholder="Search products…"/><select v-model="category" @change="load" class="rounded-xl border bg-white px-4 py-3"><option value="">All categories</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select></div><div v-if="loading" class="py-20 text-center">Loading catalog…</div><div v-else class="mt-7 grid gap-5 sm:grid-cols-2 lg:grid-cols-4"><article v-for="p in products" :key="p.id" class="overflow-hidden rounded-2xl border bg-white"><RouterLink :to="'/products/'+p.slug"><div class="aspect-square bg-slate-100"><img v-if="p.imageUrl" :src="p.imageUrl" class="h-full w-full object-cover"/></div><div class="p-4"><h2 class="font-bold">{{p.name}}</h2><p class="mt-2 text-lg font-black text-indigo-600">{{Number(p.price).toLocaleString()}} {{p.currency||'ETB'}}</p></div></RouterLink><button @click="addToCart(p)" class="m-4 mt-0 w-[calc(100%-2rem)] rounded-xl bg-slate-950 py-3 font-bold text-white">Add to cart</button></article></div></section></template>